// x86-64 runtime: module loader, dispatcher and helpers for the code
// generated by tools/lift64.py. See rt64.h for the memory model.
#include "rt64.h"

#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <time.h>

#define RT64_MAX_MODULES 16
#define RT64_IMPORT_STRIDE 16
// Return address pushed by rt64_call: never guest code (non-canonical).
#define RT64_SENTINEL UINT64_C(0xdead5e0000000000)

typedef struct {
    const RT64Module *module;
    uint64_t base;
    uint64_t imports;              // PROT_NONE range: one address per import
    rt64_shim *shims;
} Loaded;
static Loaded loaded[RT64_MAX_MODULES];
static size_t loaded_count;

void rt64_trap(CPU64 *c, uint64_t pc, const char *why) {
    fprintf(stderr, "rt64: trap at %#llx: %s (rsp %#llx)\n", (unsigned long long)pc, why,
            c ? (unsigned long long)c->r[RSP] : 0ull);
    for (size_t i = 0; i < loaded_count; ++i)
        if (pc >= loaded[i].base && pc < loaded[i].base + loaded[i].module->size)
            fprintf(stderr, "rt64:   %s+%#llx\n", loaded[i].module->name, (unsigned long long)(pc - loaded[i].base));
    abort();
}

void rt64_bad_return(CPU64 *c, uint64_t expected) {
    char why[96];
    snprintf(why, sizeof why, "returned to %#llx instead of %#llx (longjmp/exceptions are not supported yet)",
             (unsigned long long)c->rip, (unsigned long long)expected);
    rt64_trap(c, expected, why);
}

static const Loaded *find_loaded(const RT64Module *module) {
    for (size_t i = 0; i < loaded_count; ++i)
        if (loaded[i].module == module) return &loaded[i];
    return NULL;
}

uint64_t rt64_import_address(const RT64Module *module, size_t index) {
    const Loaded *l = find_loaded(module);
    return l && index < module->import_count ? l->imports + RT64_IMPORT_STRIDE * index : 0;
}

int rt64_load(const RT64Module *module, const char *image_path) {
    if (loaded_count == RT64_MAX_MODULES) return -1;
    if (!image_path) image_path = module->image_path;
    FILE *f = fopen(image_path, "rb");
    if (!f) { fprintf(stderr, "rt64: %s: %s\n", image_path, strerror(errno)); return -1; }
    uint8_t *base = mmap(NULL, module->size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    size_t got = base == MAP_FAILED ? 0 : fread(base, 1, module->size, f);
    fclose(f);
    if (base == MAP_FAILED || got != module->size) {
        fprintf(stderr, "rt64: %s: short image (%zu of %llu bytes)\n", image_path, got, (unsigned long long)module->size);
        return -1;
    }
    size_t import_span = RT64_IMPORT_STRIDE * (module->import_count ? module->import_count : 1);
    void *imports = mmap(NULL, import_span, PROT_NONE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (imports == MAP_FAILED) return -1;
    Loaded *l = &loaded[loaded_count];
    l->module = module; l->base = (uint64_t)(uintptr_t)base; l->imports = (uint64_t)(uintptr_t)imports;
    l->shims = calloc(module->import_count + 1, sizeof *l->shims);
    for (size_t i = 0; i < module->import_count; ++i) l->shims[i] = rt64_find_shim(module->imports[i]);
    *module->base = l->base;
    for (size_t i = 0; i < module->reloc_count; ++i) {
        const RT64Reloc *r = &module->relocs[i];
        uint64_t value;
        switch (r->kind) {
        case RT64_REL_BASE: value = l->base + (uint64_t)r->addend; break;
        case RT64_REL_IMPORT: value = l->imports + RT64_IMPORT_STRIDE * r->index + (uint64_t)r->addend; break;
        default: value = (uint64_t)r->addend; break;
        }
        memcpy(base + r->offset, &value, 8);
    }
    loaded_count++;
    return 0;
}

uint64_t rt64_export(const RT64Module *module, const char *name) {
    const Loaded *l = find_loaded(module);
    if (!l) return 0;
    for (size_t i = 0; i < module->export_count; ++i)
        if (!strcmp(module->exports[i].name, name)) return l->base + module->exports[i].offset;
    return 0;
}

void rt64_cpu_init(CPU64 *c, uint64_t stack_top) {
    memset(c, 0, sizeof *c);
    c->r[RSP] = stack_top & ~UINT64_C(15);
    c->mxcsr = 0x1f80;
    c->fcw = 0x37f;
}

static gfn64 lookup(const Loaded *l, uint64_t offset) {
    size_t lo = 0, hi = l->module->function_count;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        uint64_t at = l->module->functions[mid].offset;
        if (at == offset) return l->module->functions[mid].fn;
        if (at < offset) lo = mid + 1; else hi = mid;
    }
    return NULL;
}

void rt64_dispatch(CPU64 *c, uint64_t target) {
    for (size_t i = 0; i < loaded_count; ++i) {
        const Loaded *l = &loaded[i];
        if (target >= l->imports && target < l->imports + RT64_IMPORT_STRIDE * l->module->import_count) {
            size_t index = (target - l->imports) / RT64_IMPORT_STRIDE;
            if (!l->shims[index]) {
                char why[160];
                snprintf(why, sizeof why, "call to unimplemented import %s", l->module->imports[index]);
                rt64_trap(c, target, why);
            }
            l->shims[index](c);
            c->rip = POP64(c);        // the shim returns like a guest RET
            return;
        }
        if (target >= l->base && target < l->base + l->module->size) {
            gfn64 fn = lookup(l, target - l->base);
            if (!fn) rt64_trap(c, target, "indirect transfer to code that was not lifted");
            fn(c);
            return;
        }
    }
    rt64_trap(c, target, "indirect transfer outside every lifted module");
}

void rt64_call(CPU64 *c, uint64_t target) {
    PUSH64(c, RT64_SENTINEL);
    rt64_dispatch(c, target);
    if (c->rip != RT64_SENTINEL) rt64_bad_return(c, RT64_SENTINEL);
}

void rt64_cpuid(CPU64 *c) {
    // What the lifter implements (tools/lift64.py, simd64.py, x87_64.py):
    // x86-64 baseline (x87, MMX, SSE, SSE2, CMPXCHG16B), SSE3, SSSE3, SSE4.1,
    // POPCNT, LZCNT, BMI1, BMI2. Not reported, so code that checks CPUID keeps
    // to the paths above: SSE4.2, AVX and later, AES-NI, PCLMULQDQ, RDRAND...
    uint32_t leaf = (uint32_t)c->r[RAX], sub = (uint32_t)c->r[RCX];
    uint32_t a = 0, b = 0, cx = 0, d = 0;
    if (leaf == 0) { a = 7; b = 0x756e6547; d = 0x49656e69; cx = 0x6c65746e; }    // "GenuineIntel"
    else if (leaf == 1) {
        a = 0x000306a9; b = 0x00010800;
        cx = (1u << 0) | (1u << 9) | (1u << 13) | (1u << 19) | (1u << 23);       // SSE3 SSSE3 CX16 SSE4.1 POPCNT
        d = (1u << 0) | (1u << 4) | (1u << 8) | (1u << 15) | (1u << 23) | (1u << 24) | (1u << 25) | (1u << 26);
    } else if (leaf == 7 && sub == 0) b = (1u << 3) | (1u << 8);                 // BMI1 BMI2
    else if (leaf == 0x80000000u) a = 0x80000001u;
    else if (leaf == 0x80000001u) { cx = (1u << 0) | (1u << 5); d = (1u << 29) | (1u << 11); }   // LAHF LZCNT, LM SYSCALL
    c->r[RAX] = a; c->r[RBX] = b; c->r[RCX] = cx; c->r[RDX] = d;
}

uint64_t rt64_rdtsc(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    return (uint64_t)ts.tv_sec * 1000000000u + (uint64_t)ts.tv_nsec;
}

// DIV/IDIV r/m{8,16,32,64}: dividend in AX, DX:AX, EDX:EAX or RDX:RAX.
void rt64_div(CPU64 *c, uint64_t divisor, int width, int is_signed, uint64_t pc) {
    uint64_t mask = MSK64(width);
    divisor &= mask;
    if (!divisor) rt64_trap(c, pc, "#DE: division by zero");
    if (width == 8) {
        uint64_t ax = c->r[RAX] & 0xffff, q, r;
        if (is_signed) {
            int64_t n = (int16_t)ax, d = (int8_t)divisor, qq = n / d;
            if (qq < -128 || qq > 127) rt64_trap(c, pc, "#DE: quotient overflow");
            q = (uint64_t)qq & 0xff; r = (uint64_t)(n % d) & 0xff;
        } else {
            q = ax / divisor; r = ax % divisor;
            if (q > 0xff) rt64_trap(c, pc, "#DE: quotient overflow");
        }
        c->r[RAX] = (c->r[RAX] & ~UINT64_C(0xffff)) | (r << 8) | q;
        return;
    }
    unsigned __int128 n = ((unsigned __int128)(c->r[RDX] & mask) << width) | (c->r[RAX] & mask);
    uint64_t q, r;
    if (is_signed) {
        __int128 sn = width == 64 ? (__int128)n : (__int128)(int64_t)sx64((uint64_t)n, 2 * width);
        __int128 sd = (int64_t)sx64(divisor, width), qq = sn / sd;
        __int128 limit = (__int128)1 << (width - 1);
        if (qq < -limit || qq >= limit) rt64_trap(c, pc, "#DE: quotient overflow");
        q = (uint64_t)qq & mask; r = (uint64_t)(sn % sd) & mask;
    } else {
        unsigned __int128 qq = n / divisor;
        if (qq > mask) rt64_trap(c, pc, "#DE: quotient overflow");
        q = (uint64_t)qq; r = (uint64_t)(n % divisor);
    }
    if (width == 32) { c->r[RAX] = q; c->r[RDX] = r; }
    else if (width == 64) { c->r[RAX] = q; c->r[RDX] = r; }
    else { c->r[RAX] = (c->r[RAX] & ~mask) | q; c->r[RDX] = (c->r[RDX] & ~mask) | r; }
}

// x87 80-bit extended format: 64-bit mantissa with an explicit integer bit,
// 15-bit exponent (bias 16383), sign.
double rt64_ld80(uint64_t address) {
    uint64_t mantissa; uint16_t top;
    memcpy(&mantissa, (const void *)(uintptr_t)address, 8);
    memcpy(&top, (const void *)(uintptr_t)(address + 8), 2);
    int sign = top >> 15, exponent = top & 0x7fff;
    double value;
    if (exponent == 0x7fff) value = (mantissa << 1) ? __builtin_nan("") : __builtin_inf();
    else if (!exponent && !mantissa) value = 0.0;
    else value = ldexp((double)mantissa, (exponent ? exponent : 1) - 16383 - 63);
    return sign ? -value : value;
}

void rt64_st80(uint64_t address, double value) {
    uint64_t mantissa = 0; uint16_t top = __builtin_signbit(value) ? 0x8000 : 0;
    double magnitude = __builtin_fabs(value);
    if (magnitude != magnitude) { top |= 0x7fff; mantissa = UINT64_C(0xc000000000000000); }
    else if (__builtin_isinf(magnitude)) { top |= 0x7fff; mantissa = UINT64_C(1) << 63; }
    else if (magnitude != 0) {
        int exponent;
        double fraction = frexp(magnitude, &exponent);          // [0.5, 1)
        mantissa = (uint64_t)ldexp(fraction, 64);
        top |= (uint16_t)(exponent - 1 + 16383);
    }
    memcpy((void *)(uintptr_t)address, &mantissa, 8);
    memcpy((void *)(uintptr_t)(address + 8), &top, 2);
}

double rt64_x87_round(CPU64 *c, double value) {
    switch ((c->fcw >> 10) & 3) {
    case 1: return floor(value);
    case 2: return ceil(value);
    case 3: return trunc(value);
    default: return nearbyint(value);
    }
}

void rt64_fpu_state(CPU64 *c, uint64_t address, int kind) {
    uint8_t *p = (uint8_t *)(uintptr_t)address;
    uint16_t fsw = (uint16_t)((c->fsw & ~0x3800u) | ((c->ftop & 7u) << 11));
    switch (kind) {
    case 0: case 2:      // FNSTENV / FNSAVE: 28-byte environment (+ 8 x 10-byte registers)
        memset(p, 0, 28);
        memcpy(p, &c->fcw, 2); memcpy(p + 4, &fsw, 2);
        if (kind == 2) {
            for (int i = 0; i < 8; ++i) rt64_st80(address + 28 + 10 * i, c->st[(c->ftop + i) & 7]);
            c->ftop = 0; c->fcw = 0x37f; c->fsw = 0;
        }
        break;
    case 1: case 3:      // FLDENV / FRSTOR
        memcpy(&c->fcw, p, 2); memcpy(&c->fsw, p + 4, 2);
        c->ftop = (c->fsw >> 11) & 7;
        if (kind == 3) for (int i = 0; i < 8; ++i) c->st[(c->ftop + i) & 7] = rt64_ld80(address + 28 + 10 * i);
        break;
    case 4:              // FXSAVE: 512 bytes
        memset(p, 0, 512);
        memcpy(p, &c->fcw, 2); memcpy(p + 2, &fsw, 2); memcpy(p + 24, &c->mxcsr, 4);
        { uint32_t mask = 0xffff; memcpy(p + 28, &mask, 4); }
        for (int i = 0; i < 8; ++i) rt64_st80(address + 32 + 16 * i, c->st[(c->ftop + i) & 7]);
        memcpy(p + 160, c->xmm, 16 * 16);
        break;
    default:             // FXRSTOR
        memcpy(&c->fcw, p, 2); memcpy(&c->fsw, p + 2, 2); memcpy(&c->mxcsr, p + 24, 4);
        c->ftop = (c->fsw >> 11) & 7;
        for (int i = 0; i < 8; ++i) c->st[(c->ftop + i) & 7] = rt64_ld80(address + 32 + 16 * i);
        memcpy(c->xmm, p + 160, 16 * 16);
        break;
    }
}
